# Surah At-Tawbah (chapter 9) — part 14: ayat 125-129 (IDs 1360-1364)
SURAH = 9

ENTRIES = {
1360: (
"اور — وہ لوگ — جن — کے دلوں میں — بیماری ہے — تو — انہیں — یہ — ان کے — ناپاک میں — مزید — ناپاک کرتا ہے — اور — وہ — کافر حالت میں — مرے",
"""۱۔ دل میں بیماری والا شخص — قرآن سن کر بھی — زیادہ — بگڑ جاتا ہے۔
۲۔ ’’وَأَمَّا الَّذِينَ فِي قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَىٰ رِجْسِهِمْ وَمَاتُوا وَهُمْ كَافِرُونَ‘‘ — اور — وہ لوگ — جن — کے دلوں میں — بیماری ہے — تو — انہیں — یہ — ان کے — ناپاک میں — مزید — ناپاک کرتا ہے — اور — وہ — کافر حالت میں — مرے — یعنی قرآن — منافقوں کے دلوں کی — ناپاکی — بڑھا دیتا ہے؛ وہ — کافر حالت میں — مرتے ہیں۔
۳۔ عملی سبق: دل کی بیماری — قرآن سے — بڑھتی ہے — علاج — توبہ — ہے۔"""
),
1361: (
"کیا — وہ — نہیں دیکھتے — کہ — وہ — ہر سال — ایک یا دو بار — آزمائے جاتے ہیں — پھر بھی — وہ — توبہ نہیں کرتے — اور — نہ — وہ — نصیحت حاصل کرتے ہیں",
"""۱۔ منافق — ہر سال آزمائے جاتے ہیں — مگر — توبہ نہیں کرتے۔
۲۔ ’’أَوَلَا يَرَوْنَ أَنَّهُمْ يُفْتَنُونَ فِي كُلِّ عَامٍ مَّرَّةً أَوْ مَرَّتَيْنِ ثُمَّ لَا يَتُوبُونَ وَلَا هُمْ يَذَّكَّرُونَ‘‘ — کیا — وہ — نہیں دیکھتے — کہ — وہ — ہر سال — ایک یا دو بار — آزمائے جاتے ہیں — پھر بھی — وہ — توبہ نہیں کرتے — اور — نہ — وہ — نصیحت حاصل کرتے ہیں — یعنی منافق — ہر سال — ایک دو آزمائشوں کے باوجود — توبہ نہیں کرتے — اور نصیحت حاصل نہیں کرتے۔
۳۔ عملی سبق: آزمائش — توبہ کا — بہترین — موقع ہے۔"""
),
1362: (
"اور — جب — کوئی سورہ — اتاری جاتی ہے — تو — وہ — ایک دوسرے — کی طرف — دیکھتے ہیں — کیا — کوئی — آپ کو — دیکھ رہا ہے — پھر — وہ — آنکھ پھیر لیتے ہیں — اللہ — نے — ان کے دل — پھیر دیے — اس لیے کہ — وہ — ایک — قوم ہیں — جو — نہیں سمجھتے",
"""۱۔ منافق — سورہ — کے اترنے پر — ایک دوسرے کی طرف — دیکھتے ہیں — چھپ چھپانے کے لیے۔
۲۔ ’’وَإِذَا مَا أُنزِلَتْ سُورَۃٌ نَّظَرَ بَعْضُهُمْ إِلَىٰ بَعْضٍ هَلْ يَرَاكُم مِّنْ أَحَدٍ ثُمَّ انصَرَفُوا صَرَفَ اللَّهُ قُلُوبَهُم بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ‘‘ — اور — جب — کوئی سورہ — اتاری جاتی ہے — تو — وہ — ایک دوسرے — کی طرف — دیکھتے ہیں — کیا — کوئی — آپ کو — دیکھ رہا ہے — پھر — وہ — آنکھ پھیر لیتے ہیں — اللہ — نے — ان کے دل — پھیر دیے — اس لیے کہ — وہ — ایک — قوم ہیں — جو — نہیں سمجھتے — یعنی منافق — سورہ — کے اترنے پر — ایک دوسرے کی طرف دیکھتے ہیں — کیا کوئی دیکھ — رہا ہے؛ اللہ نے — ان کے دل — پھیر دیے ہیں۔
۳۔ عملی سبق: دل اگر مسخ ہو جائے — تو — بات — بھی — سمجھ — نہیں آتی۔"""
),
1363: (
"یقیناً — تمہارے پاس — تم میں سے — ایک رسولؐ — آئے — جن — کو — تمہاری تکلیف — بہت — سخت لگتی ہے — جو — تمہارے بھلے — کے — بہت — خواہاں ہیں — مؤمنوں پر — مہربان رحم کرنے والے ہیں",
"""۱۔ نبیؐ — تم میں سے — ہیں — تمہارے لیے — غم خوار اور مؤمنوں پر مہربان۔
۲۔ ’’لَقَدْ جَاءَكُمْ رَسُولٌ مِّنْ أَنفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُم بِالْمُؤْمِنِينَ رَءُوفٌ رَّحِيمٌ‘‘ — یقیناً — تمہارے پاس — تم میں سے — ایک رسولؐ — آئے — جن — کو — تمہاری تکلیف — بہت — سخت لگتی ہے — جو — تمہارے بھلے — کے — بہت — خواہاں ہیں — مؤمنوں پر — مہربان رحم کرنے والے ہیں — یعنی نبیؐ — تمہارے میں سے ہیں — تمہاری تکلیف — ان پر — بہت — سخت لگتی ہے؛ وہ — تمہارے بھلے کے خواہاں ہیں — مؤمنوں پر مہربان رحم کرنے والے ہیں۔
۳۔ عملی سبق: نبیؐ — تمہارے — سب سے بڑے خیر خواہ ہیں؛ ان کی پیروی کرو۔"""
),
1364: (
"پس — اگر — وہ — منہ موڑ لیں — تو کہدو — اللہ — میرے لیے کافی ہے — اس کے سوا — کوئی — معبود نہیں — اسی پر — میں نے — بھروسہ کیا — اور — وہ — عرشِ عظیم — کا رب ہے",
"""۱۔ رسولؐ — اللہ پر بھروسہ رکھتے ہیں — مخالفین کے باوجود۔
۲۔ ’’فَإِن تَوَلَّوْا فَقُلْ حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ‘‘ — پس — اگر — وہ — منہ موڑ لیں — تو کہدو — اللہ — میرے لیے کافی ہے — اس کے سوا — کوئی — معبود نہیں — اسی پر — میں نے — بھروسہ کیا — اور — وہ — عرشِ عظیم — کا رب ہے — یعنی مخالفین — کتنا ہی کریں — اللہ — نبیؐ کے لیے کافی ہے؛ وہ — عرشِ عظیم کا رب ہے۔
۳۔ عملی سبق: اللہ — سب کا کارساز ہے — اور — عرشِ عظیم کا مالک ہے؛ ہر حال میں — اس پر بھروسہ کرو۔"""
),
}
